#include <stdio.h>

int next_local(void)
{
    int n = 0;
    n++;
    return n;
}

int main(void)
{
    printf("%d\n", next_local());
    printf("%d\n", next_local());
    return 0;
}

#include <stdio.h>

int next_static(void)
{
    static int n = 0;
    n++;
    return n;
}

int main(void)
{
    printf("%d\n", next_static());
    printf("%d\n", next_static());
    return 0;
}

#include <stdio.h>

int main(void)
{
    int x = 2;
    {
        int x = 9;
        printf("%d\n", x);
    }
    printf("%d\n", x);
    return 0;
}

#include <stdio.h>

int twice(int n)
{
    return n * 2;
}

int main(void)
{
    printf("%d %d\n", twice(4), twice(4));
    return 0;
}

